270	```javascript
271	// A word is a run of letters or digits (any script), optionally joined to the
272	// next run by a single apostrophe (straight or typographic) or hyphen. The
273	// joiners are only part of a word when letters or digits sit on both sides, so
274	// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
275	// em dashes, periods and underscores, separates words.
276	const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;
277	
278	function assertText(fn, value) {
279	  if (typeof value !== 'string') {
280	    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
281	  }
282	}
283	
284	// Private: the single definition of "word" shared by every statistic below.
285	function tokenize(text) {
286	  return text.match(WORD_PATTERN) ?? [];
287	}
288	
289	/**
290	 * Count the words in a piece of text.
291	 *
292	 * @param {string} text
293	 * @returns {number}
294	 */
295	function wordCount(text) {
296	  assertText('wordCount', text);
297	  return tokenize(text).length;
298	}
299	
300	module.exports = { wordCount };
301	```
