832	
833	```javascript
834	// Function words that would otherwise crowd every ranking. The list is
835	// deliberately short and fixed: callers who need a different list can filter
836	// the full ranking (pass a large n) themselves.
837	const STOP_WORDS = new Set([
838	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
839	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
840	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
841	  'will', 'with',
842	]);
843	
844	/**
845	 * List the most frequent words in a piece of text.
846	 *
847	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
848	 * and stop words are skipped. Entries are ordered by count (highest first),
849	 * then alphabetically, so the result is deterministic.
850	 *
851	 * @param {string} text
852	 * @param {number} n How many entries to return; a non-negative integer.
853	 * @returns {Array<{word: string, count: number}>}
854	 */
855	function topWords(text, n) {
856	  assertText('topWords', text);
857	  if (!Number.isInteger(n) || n < 0) {
858	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
859	  }
860	  const counts = new Map();
861	  for (const token of tokenize(text)) {
862	    const word = token.toLowerCase().replace(/’/g, "'");
863	    if (STOP_WORDS.has(word)) {
864	      continue;
865	    }
866	    counts.set(word, (counts.get(word) ?? 0) + 1);
867	  }
868	  return [...counts]
869	    .map(([word, count]) => ({ word, count }))
870	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
871	    .slice(0, n);
872	}
873	
874	module.exports = { wordCount, sentenceCount, topWords };
875	```
