1073	const DEFAULT_WORDS_PER_MINUTE = 200;
1074	
1075	/**
1076	 * Estimate how many whole minutes a text takes to read.
1077	 *
1078	 * The estimate is the word count divided by the reading rate, rounded up, so
1079	 * any text with at least one word takes at least a minute and the empty text
1080	 * takes none.
1081	 *
1082	 * @param {string} text
1083	 * @param {number} [wpm=200] Reading rate in words per minute; a positive, finite number.
1084	 * @returns {number} Whole minutes.
1085	 */
1086	function readingTimeMinutes(text, wpm = DEFAULT_WORDS_PER_MINUTE) {
1087	  assertText('readingTimeMinutes', text);
1088	  if (typeof wpm !== 'number' || !Number.isFinite(wpm) || wpm <= 0) {
1089	    throw new RangeError(`readingTimeMinutes: wpm must be a positive finite number, received ${String(wpm)}`);
1090	  }
1091	  return Math.ceil(wordCount(text) / wpm);
1092	}
1093	
1094	module.exports = { wordCount, sentenceCount, topWords, readingTimeMinutes };
1095	```
